assert len(functions) == len(CASES) == 24
common = [
 'Each test owns all in-memory values and directly calls public frozen production celld_logic components; no substitute decision implementation',
 'Storage PUT/delete success, failure, CAS ordering, member confirmations and restore chains are explicit synthetic environmental facts; no disk, bucket, network, actor or VM is exercised',
 'Every supplied finish_recovery certificate has a stipulated prior durable per-cell/bucket receipt; the pure finish function does not validate that I/O premise',
 'GC chains are supplied from the stipulated production restore walk, oldest-first and ending at own epoch except the deliberate missing-opener schedules; no restore walk is reimplemented',
 'GC listed vectors intentionally include base/own/off-chain epochs beyond the current executor scan.below input; these are public-component API robustness premises, not claimed live executor traces',
 'Hash checks must match delivered runtime manifest lineage before future review/build/run; no compiler or SUT was launched while authoring',
]
manifest = []
for row, fn in zip(CASES, functions):
    cid, intent, hypothesis, initial, trace, stress, safety, liveness, contract = row
    assert fn.startswith(cid.lower()+'_')
    manifest.append(dict(
        id=cid, intent=intent, failure_hypothesis=hypothesis, preconditions=common,
        initial_state=initial, trace=trace, stress=stress+'; <=100 receipt observations, <=7 listed epochs, <=2 members per ensemble, <=3 unique follower identities per case and finite explicit operations',
        safety_oracle=safety, liveness_oracle=liveness, oracle=safety+'; '+liveness,
        terminal_witness='END '+cid+' after assertion-bearing observations; external resources=0',
        cleanup='Drop only this test-owned records, maps, fragments, health tracker and ledger. No external resources exist; unwind also drops all owned values.',
        implementation='tests/log_recovery.rs:'+fn, test_function=fn,
        source_contract=contract, layer='native-component', sublayer='public-component-model-trace',
        classification='characterization' if cid=='J022' else 'promotion-candidate',
        qualification='Native pure-component decisions conditional on stated synthetic environmental facts; never real durable-storage, actor, VM, OS, tenant-boundary or security proof',
        promotion=False, authored=True, reviewed=False, executable=True, compiler_verified=False,
        run=False, passed=False, status='NOT_RUN', source_pins='source-pins.json', profile='profile.json',
    ))
(W/'manifest.json').write_text(json.dumps(manifest, indent=2)+'\n')

runtime=json.loads(RUNTIME.read_text())
production={p.name:sha(p) for p in sorted(ROOT.iterdir()) if p.suffix=='.rs' or p.name=='Cargo.toml'}
for name,digest in production.items():
    assert runtime['source_hashes']['celld/crates/logic/'+name]==digest, name
context_paths=['celld/crates/celld/node_log.rs','celld/crates/celld/ltx_repl.rs','celld/docs/testing.md']
context={name:sha(PROJECT/name) for name in context_paths}
for name,digest in context.items():
    assert runtime['source_hashes'][name]==digest, name
compared=['output-gate-logic','routing-acquisition-logic','durable-recovery-stress','pressure-recovery-logic']
pins=dict(schema=1, source_root=str(ROOT), production_files=production,
    context_root=str(PROJECT), context_files=context,
    delivered_runtime_sha256=runtime['binary_sha256'],
    runtime_manifest=dict(path=str(RUNTIME),sha256=sha(RUNTIME)),
    test_files={name:sha(W/name) for name in ['Cargo.toml','Cargo.lock','tests/log_recovery.rs']},
    comparison_manifest_hashes={name:sha(W.parent/name/'manifest.json') for name in compared},
    counting_policy=dict(path=str(W.parents[1]/'COUNTING-POLICY.md'),sha256=sha(W.parents[1]/'COUNTING-POLICY.md')),
    limitation='Runtime digest is frozen lineage only. Native test executable has not been compiled or run. No binary is opened by this script.')
(W/'source-pins.json').write_text(json.dumps(pins,indent=2)+'\n')
(W/'inventory.json').write_text(json.dumps(dict(authored=24,reviewed=0,executable_source=24,compiler_verified=0,run=0,passed=0,promotion_candidates=23,nonpromoting_characterization=1,ids=[r[0] for r in CASES]),indent=2)+'\n')
